"""RoboPaint record. All robot interaction uses the standard client only."""
import sys, json, time, math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output')
class Painter:
 def __init__(self):
  self.r=Robot(); self.s=self.r.spec(); o=self.r.get_obs(cameras=[]); self.p=np.array(o.meta['proprio']['now'][7:14]); self.quat=self.p[3:].copy(); self.rows=[]; self.n=0
 def go(self,xyz,seconds=None,speed=.13):
  dest=np.r_[xyz,self.quat]; dist=np.linalg.norm(dest[:3]-self.p[:3]); n=max(1,math.ceil((seconds if seconds is not None else max(.15,dist/speed))/.05))
  for a in np.linspace(0,1,n+1)[1:]: self.rows.append((self.p*(1-a)+dest*a).tolist())
  self.p=dest
 def flush(self,cameras=[]):
  while self.rows:
   rows=self.rows[:190]; self.rows=self.rows[190:]
   before=self.r.status(); np.save(OUT/'pending.npy',rows)
   try: res=self.r.submit('ee_pose',rows,dt=.05,cameras=cameras,video='none')
   except Exception:
    self.r.wait_ready(); after=self.r.status()
    if after['control_steps']==before['control_steps']: res=self.r.submit('ee_pose',rows,dt=.05,cameras=cameras,video='none')
    else: raise
   with open(OUT/'actions.jsonl','a') as f: f.write(json.dumps({'rows':rows,'steps':res.meta.get('control_steps'),'plan':res.meta.get('plan')})+'\n')
   self.n+=1
  return res
 def park(self):
  self.go([self.p[0],self.p[1],.065]); self.go([-.32,0,.13]); self.flush()
 def obs(self,name,cameras=['canvas_cam','scene_cam','practice_cam']):
  o=self.r.get_obs(cameras=cameras,depth=True); o.save(str(OUT/name));
  for c,a in o.last.items(): Image.fromarray(a).save(OUT/(name+'_'+c+'.png'))
  return o
if __name__=='__main__':
 p=Painter(); p.park(); p.obs('clear'); print(p.r.status())
