 float best=-1e30;int col=0;
 for(int c=0;c<16;c++){float z=C;for(int k=0;k<3;k++)z+=2*pal[c*3+k]*B[k]-A*pal[c*3+k]*pal[c*3+k];if(z>best){best=z;col=c;}}
